package com.appli.nutristat;
import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.content.*;import java.time.*;import java.util.*;
public class MainActivity extends Activity{
 NutriDb db;LinearLayout content;Spinner profiles;NutriDb.Profile profile;int tab=0;
 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} TextView t(String s,int z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setPadding(dp(7),dp(7),dp(7),dp(7));if(b)v.setTypeface(null,1);return v;} Button b(String s){Button v=new Button(this);v.setText(s);v.setAllCaps(false);return v;} EditText e(String h,String s){EditText v=new EditText(this);v.setHint(h);v.setText(s);v.setSingleLine();return v;}double n(EditText e,double d){try{return Double.parseDouble(e.getText().toString().replace(',','.'));}catch(Exception x){return d;}}int ni(EditText e,int d){try{return Integer.parseInt(e.getText().toString());}catch(Exception x){return d;}}
 public void onCreate(Bundle x){super.onCreate(x);db=new NutriDb(this);shell();loadProfiles(0);}
 void shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(t("Nutristat",25,true),new LinearLayout.LayoutParams(0,dp(55),1));profiles=new Spinner(this);head.addView(profiles,new LinearLayout.LayoutParams(dp(160),dp(55)));root.addView(head);ScrollView sv=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(12),dp(5),dp(12),dp(8));sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);String[] a={"Aujourd'hui","Calendrier","+ Repas","Stats","Profil"};for(int i=0;i<a.length;i++){final int k=i;Button q=b(a[i]);q.setTextSize(11);q.setOnClickListener(v->{tab=k;render();});nav.addView(q,new LinearLayout.LayoutParams(0,dp(58),1));}root.addView(nav);setContentView(root);profiles.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){List<NutriDb.Profile>a=db.profiles();if(i<a.size()){profile=a.get(i);render();}}});}
 void loadProfiles(long id){List<NutriDb.Profile>a=db.profiles();profiles.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));int z=0;for(int i=0;i<a.size();i++)if(a.get(i).id==id)z=i;profiles.setSelection(z);if(!a.isEmpty())profile=a.get(z);render();}
 void render(){if(profile==null)return;content.removeAllViews();if(tab==0)today();else if(tab==1)calendar();else if(tab==2)add();else if(tab==3)stats();else profile();}
 void progress(String name,double v,double goal){content.addView(t(name+"   "+String.format(Locale.FRANCE,"%.1f",v)+" / "+String.format(Locale.FRANCE,"%.1f",goal),14,true));ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(100);p.setProgress(goal<=0?0:(int)Math.min(100,100*v/goal));content.addView(p,new LinearLayout.LayoutParams(-1,dp(16)));}
 void today(){String d=LocalDate.now().toString();NutriDb.Nutrients n=db.totals(profile.id,d);content.addView(t("Bilan du jour",21,true));content.addView(t(Math.round(n.cal)+" / "+Math.round(profile.cal)+" kcal",27,true));progress("Protéines (g)",n.protein,profile.protein);progress("Glucides (g)",n.carbs,profile.carbs);progress("Lipides (g)",n.fat,profile.fat);progress("Fibres (g)",n.fiber,profile.fiber);progress("Sucres (g max)",n.sugar,profile.sugar);content.addView(t("Repas",19,true));List<NutriDb.Meal> ms=db.meals(profile.id,d);if(ms.isEmpty())content.addView(t("Aucun repas enregistré.",14,false));for(NutriDb.Meal m:ms)content.addView(t(m.meal+" — "+m.item+" · "+m.amount+" · "+Math.round(m.cal)+" kcal",14,false));Button q=b("Ajouter un repas");q.setOnClickListener(v->{tab=2;render();});content.addView(q);}
 void calendar(){content.addView(t("Calendrier",21,true));CalendarView cv=new CalendarView(this);content.addView(cv,new LinearLayout.LayoutParams(-1,dp(320)));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);content.addView(box);showDay(box,LocalDate.now().toString());cv.setOnDateChangeListener((v,y,m,d)->showDay(box,String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d)));}
 void showDay(LinearLayout box,String date){box.removeAllViews();NutriDb.Nutrients n=db.totals(profile.id,date);box.addView(t(date+" · "+Math.round(n.cal)+" kcal · P "+Math.round(n.protein)+" · G "+Math.round(n.carbs)+" · L "+Math.round(n.fat)+" · Fibres "+Math.round(n.fiber)+" · Sucre "+Math.round(n.sugar),14,true));for(NutriDb.Meal m:db.meals(profile.id,date))box.addView(t(m.meal+" — "+m.item+" ("+m.amount+")",13,false));}
 void add(){content.addView(t("Ajouter",21,true));Button m=b("Ajouter une consommation");m.setOnClickListener(v->mealDialog());content.addView(m);Button f=b("Créer un aliment");f.setOnClickListener(v->foodDialog());content.addView(f);Button r=b("Créer une recette / un plat");r.setOnClickListener(v->recipeDialog());content.addView(r);content.addView(t("Base alimentaire",18,true));for(NutriDb.Food x:db.foods())content.addView(t(x.name+" · 100 g: "+Math.round(x.cal)+" kcal · P "+x.protein+" · G "+x.carbs+" · L "+x.fat+" · Fibres "+x.fiber+" · Sucres "+x.sugar,13,false));for(NutriDb.Recipe x:db.recipes())content.addView(t("Recette: "+x.name+" · "+Math.round(x.cal)+" kcal/part",13,true));}
 void mealDialog(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText date=e("Date",LocalDate.now().toString()),meal=e("Repas","Déjeuner"),qty=e("Quantité","100");Spinner type=new Spinner(this),item=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Aliment","Recette"}));l.addView(date);l.addView(meal);l.addView(type);l.addView(item);l.addView(qty);Runnable load=()->{if(type.getSelectedItemPosition()==0)item.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.foods()));else item.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.recipes()));};load.run();type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){qty.setText(i==0?"100":"1");load.run();}});new AlertDialog.Builder(this).setTitle("Ajouter au repas").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Ajouter",(d,w)->{double q=n(qty,1);if(type.getSelectedItemPosition()==0){NutriDb.Food f=(NutriDb.Food)item.getSelectedItem();if(f!=null)db.addMeal(profile.id,date.getText().toString(),meal.getText().toString(),f.name,q+" g",new NutriDb.Nutrients(f.cal,f.protein,f.fat,f.carbs,f.fiber,f.sugar).scale(q/100));}else{NutriDb.Recipe r=(NutriDb.Recipe)item.getSelectedItem();if(r!=null)db.addMeal(profile.id,date.getText().toString(),meal.getText().toString(),r.name,q+" part(s)",new NutriDb.Nutrients(r.cal,r.protein,r.fat,r.carbs,r.fiber,r.sugar).scale(q));}tab=0;render();}).show();}
 void foodDialog(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText name=e("Nom",""),cal=e("Calories /100g","0"),pro=e("Protéines","0"),fat=e("Lipides","0"),carb=e("Glucides","0"),fib=e("Fibres","0"),sug=e("Sucres","0");for(EditText x:new EditText[]{name,cal,pro,fat,carb,fib,sug})l.addView(x);new AlertDialog.Builder(this).setTitle("Nouvel aliment").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{if(name.length()>0)db.saveFood(new NutriDb.Food(0,name.getText().toString(),"",n(cal,0),n(pro,0),n(fat,0),n(carb,0),n(fib,0),n(sug,0)));render();}).show();}
 void recipeDialog(){List<NutriDb.Food> fs=db.foods();ArrayList<NutriDb.Ingredient> ins=new ArrayList<>();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText name=e("Nom du plat",""),parts=e("Nombre de parts","4"),grams=e("Grammes","100");Spinner food=new Spinner(this);food.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,fs));Button plus=b("+ Ajouter cet ingrédient");TextView sum=t("Aucun ingrédient",13,false);l.addView(name);l.addView(parts);l.addView(food);l.addView(grams);l.addView(plus);l.addView(sum);plus.setOnClickListener(v->{NutriDb.Food f=(NutriDb.Food)food.getSelectedItem();if(f!=null){ins.add(new NutriDb.Ingredient(f,n(grams,100)));String s="";for(NutriDb.Ingredient i:ins)s+=i.food.name+" · "+Math.round(i.grams)+" g\n";sum.setText(s);}});new AlertDialog.Builder(this).setTitle("Nouvelle recette").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{if(name.length()>0&&!ins.isEmpty())db.saveRecipe(name.getText().toString(),n(parts,1),ins);render();}).show();}
 void stats(){content.addView(t("Statistiques",21,true));LinearLayout top=new LinearLayout(this);Button a=b("7 jours"),c=b("30 jours");top.addView(a,new LinearLayout.LayoutParams(0,-2,1));top.addView(c,new LinearLayout.LayoutParams(0,-2,1));content.addView(top);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);content.addView(box);a.setOnClickListener(v->charts(box,7));c.setOnClickListener(v->charts(box,30));charts(box,7);}
 void charts(LinearLayout box,int days){box.removeAllViews();String[] names={"Calories","Protéines","Glucides","Lipides","Fibres","Sucres"};double[] goals={profile.cal,profile.protein,profile.carbs,profile.fat,profile.fiber,profile.sugar};List<NutriDb.DayStat>s=db.stats(profile.id,days);for(int i=0;i<6;i++){box.addView(t(names[i],16,true));box.addView(new Chart(this,s,i,goals[i]),new LinearLayout.LayoutParams(-1,dp(160)));}}
 void profile(){content.addView(t("Profil et objectifs",21,true));EditText name=e("Nom",profile.name),age=e("Âge",""+profile.age),weight=e("Poids kg",""+profile.weight),cal=e("Calories",""+profile.cal),pro=e("Protéines",""+profile.protein),fat=e("Lipides",""+profile.fat),carb=e("Glucides",""+profile.carbs),fib=e("Fibres",""+profile.fiber),sug=e("Sucre max",""+profile.sugar);for(EditText x:new EditText[]{name,age,weight,cal,pro,fat,carb,fib,sug})content.addView(x);Button save=b("Enregistrer");save.setOnClickListener(v->{long id=db.saveProfile(new NutriDb.Profile(profile.id,name.getText().toString(),ni(age,30),n(weight,70),n(cal,2000),n(pro,120),n(fat,70),n(carb,230),n(fib,30),n(sug,50)));db.saveWeight(id,LocalDate.now().toString(),n(weight,70));loadProfiles(id);});content.addView(save);Button add=b("+ Ajouter un utilisateur");add.setOnClickListener(v->newProfile());content.addView(add);content.addView(t("Historique du poids",18,true));for(NutriDb.WeightLog w:db.weights(profile.id))content.addView(t(w.date+" · "+w.weight+" kg",13,false));}
 void newProfile(){EditText name=e("Nom","Nouvel utilisateur");new AlertDialog.Builder(this).setTitle("Nouvel utilisateur").setView(name).setNegativeButton("Annuler",null).setPositiveButton("Créer",(d,w)->{long id=db.saveProfile(new NutriDb.Profile(0,name.getText().toString(),30,70,2000,120,70,230,30,50));loadProfiles(id);tab=4;render();}).show();}
 static class Chart extends View{List<NutriDb.DayStat>s;int m;double goal;Paint p=new Paint(1);Chart(Context c,List<NutriDb.DayStat>s,int m,double g){super(c);this.s=s;this.m=m;goal=g;setBackgroundColor(Color.rgb(248,248,248));}double val(NutriDb.Nutrients n){return m==0?n.cal:m==1?n.protein:m==2?n.carbs:m==3?n.fat:m==4?n.fiber:n.sugar;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),l=40,r=w-10,t=15,b=h-25;double max=Math.max(goal,1);for(NutriDb.DayStat d:s)max=Math.max(max,val(d.n));max*=1.15;p.setStrokeWidth(2);p.setColor(Color.GRAY);float gy=(float)(b-goal/max*(b-t));c.drawLine(l,gy,r,gy,p);p.setColor(Color.rgb(46,125,50));p.setStrokeWidth(5);float px=-1,py=-1;for(int i=0;i<s.size();i++){float x=s.size()==1?l:l+(r-l)*i/(s.size()-1),y=(float)(b-val(s.get(i).n)/max*(b-t));if(px>=0)c.drawLine(px,py,x,y,p);c.drawCircle(x,y,4,p);px=x;py=y;}}}
}
